CREATE OR REPLACE FUNCTION public.aka_agent_clear_campaign_runtime_claim_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'đang chạy'
      AND NEW.status = 'tạm dừng'
      AND OLD.runtime_claim_target = 'server'
    THEN
      -- Server run control is DB-first. A pause can commit after the executor's
      -- top-level claim committed but before that response reached the caller.
      -- Preserve the exact ownership tuple so the caller can recover the lost
      -- response, observe the paused status, and release the account only from
      -- its normal safe cleanup boundary.
      NEW.runtime_claim_token := OLD.runtime_claim_token;
      NEW.runtime_claim_target := OLD.runtime_claim_target;
      NEW.runtime_claim_vietnam_date := OLD.runtime_claim_vietnam_date;
      NEW.runtime_claimed_at := OLD.runtime_claimed_at;
    ELSE
      NEW.runtime_claim_token := NULL;
      NEW.runtime_claim_target := NULL;
      NEW.runtime_claim_vietnam_date := NULL;
      NEW.runtime_claimed_at := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_control_web_device_policy_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_limit integer;
BEGIN
  IF (TG_OP<>'INSERT' AND OLD.key='web.auth.max_devices_per_staff')
    OR (TG_OP<>'DELETE' AND NEW.key='web.auth.max_devices_per_staff') THEN
    SELECT public.aka_agent_control_web_device_limit(value,is_active,is_secret) INTO v_limit
    FROM public.auto_system_settings WHERE key='web.auth.max_devices_per_staff';
    UPDATE public.auto_control_web_device_policy SET max_devices=coalesce(v_limit,3),revision=gen_random_uuid()
    WHERE singleton AND max_devices IS DISTINCT FROM coalesce(v_limit,3);
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_guard_campaign_data_group_source_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.campaign_id IS DISTINCT FROM OLD.campaign_id THEN
    RAISE EXCEPTION 'campaign_data_group_source_identity_immutable';
  END IF;
  IF NEW.group_id IS DISTINCT FROM OLD.group_id AND EXISTS (
    SELECT 1 FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = OLD.campaign_id
      AND input_data.canonical_target_key IS NOT NULL
      AND COALESCE(input_data.is_delete, false) = false
  ) THEN
    RAISE EXCEPTION 'campaign_data_group_source_immutable_after_intake';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_guard_canonical_campaign_input_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_has_phone boolean;
  v_target_changed boolean;
BEGIN
  IF OLD.canonical_target_key IS NULL THEN
    RETURN NEW;
  END IF;

  -- Information is editable in both direct and data_group campaigns; the
  -- delivery target and ledger references are not. No alias cleanup is needed.
  IF NEW.campaign_id IS DISTINCT FROM OLD.campaign_id
    OR NEW.input_id IS DISTINCT FROM OLD.input_id
    OR NEW.canonical_target_key IS DISTINCT FROM OLD.canonical_target_key
    OR NEW.auto_automation_detail_id IS DISTINCT FROM OLD.auto_automation_detail_id
    OR NEW.is_delete IS DISTINCT FROM OLD.is_delete
  THEN
    RAISE EXCEPTION 'canonical_campaign_input_payload_immutable';
  END IF;

  -- Status, name, notes, carrier, info1..5, content and scheduling changes
  -- require no campaign lookup. Only possible target changes need the action.
  IF NEW.phone IS NOT DISTINCT FROM OLD.phone
    AND NEW.uid IS NOT DISTINCT FROM OLD.uid
    AND NEW.email IS NOT DISTINCT FROM OLD.email
  THEN
    RETURN NEW;
  END IF;

  SELECT campaign.action_id INTO v_action
  FROM public.auto_campaigns AS campaign WHERE campaign.id = OLD.campaign_id;

  IF v_action IN ('zalo_message_phone', 'sms_send', 'voice_call', 'zalo_add_group_member') THEN
    v_has_phone := COALESCE(public.normalize_phone(OLD.phone) ~ '^0[35789][0-9]{8}$', false);
    IF v_action = 'zalo_add_group_member' AND NOT v_has_phone THEN
      -- Adding a valid phone would switch this UID-based row to another route.
      v_target_changed := NEW.uid IS DISTINCT FROM OLD.uid
        OR COALESCE(public.normalize_phone(NEW.phone) ~ '^0[35789][0-9]{8}$', false);
    ELSE
      v_target_changed := NEW.phone IS DISTINCT FROM OLD.phone
        OR (NOT v_has_phone AND NEW.uid IS DISTINCT FROM OLD.uid)
        OR (v_action = 'zalo_add_group_member' AND NULLIF(btrim(OLD.uid), '') IS NOT NULL
          AND NEW.uid IS DISTINCT FROM OLD.uid);
    END IF;
  ELSIF v_action = 'email_send' THEN
    v_target_changed := NEW.email IS DISTINCT FROM OLD.email;
  ELSIF v_action LIKE 'facebook_%' OR v_action LIKE 'zalo_%' THEN
    v_target_changed := NEW.uid IS DISTINCT FROM OLD.uid;
  ELSE
    -- Unknown/legacy actions keep all potential target fields protected.
    v_target_changed := NEW.phone IS DISTINCT FROM OLD.phone
      OR NEW.uid IS DISTINCT FROM OLD.uid OR NEW.email IS DISTINCT FROM OLD.email;
  END IF;

  IF v_target_changed THEN
    RAISE EXCEPTION 'canonical_campaign_input_target_immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_resolve_automation_canonical_input()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_input_id bigint;
BEGIN
  IF NEW.status = 'đã thêm' AND OLD.status IS DISTINCT FROM 'đã thêm' THEN
    SELECT origin.input_data_id INTO v_input_id
    FROM public.auto_campaign_input_origins AS origin
    WHERE origin.origin_kind = 'automation'
      AND origin.automation_detail_id = NEW.id
    ORDER BY origin.created_at DESC, origin.id DESC
    LIMIT 1;
    IF v_input_id IS NOT NULL THEN NEW.target_input_data_id := v_input_id; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_campaign_completed_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'hoàn thành' AND OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.completed_at = now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_group_only_sync_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.target_campaign_id IS NULL
    AND NEW.target_data_group_id IS NOT NULL
    AND NEW.status IN ('bỏ qua', 'lỗi')
  THEN
    NEW.target_data_group_sync_status := 'skipped';
    NEW.target_data_group_sync_error := COALESCE(
      NEW.target_data_group_sync_error,
      NEW.last_error,
      CASE WHEN NEW.status = 'lỗi' THEN 'automation_failed' ELSE 'automation_skipped' END
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_snapshot_automation_data_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT automation.target_data_group_id INTO NEW.target_data_group_id
    FROM public.auto_automation AS automation
    WHERE automation.id = NEW.automation_id;
    NEW.target_data_group_sync_status := CASE
      WHEN NEW.target_data_group_id IS NULL THEN NULL ELSE 'pending' END;
    NEW.config_snapshot := COALESCE(NEW.config_snapshot, '{}'::jsonb)
      || jsonb_build_object('target_data_group_id', NEW.target_data_group_id);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_touch_campaign_last_run_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_detail_at timestamptz := COALESCE(NEW.created_at, now());
BEGIN
  IF NEW.campaign_id IS NULL OR COALESCE(NEW.is_delete, false) THEN
    RETURN NEW;
  END IF;

  UPDATE public.auto_campaigns
  SET last_run_at = v_detail_at,
      updated_at = now()
  WHERE id = NEW.campaign_id
    AND is_delete = false
    AND (last_run_at IS NULL OR last_run_at < v_detail_at);

  RETURN NEW;
END;
$function$

