CREATE OR REPLACE FUNCTION public.protect_zalo_chat_referral_ai_log_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old_reserved boolean := false;
  v_new_reserved boolean := false;
begin
  if tg_op in ('INSERT', 'UPDATE') then
    v_new_reserved := coalesce(new.using_code, '') = 'zalo_chat_referral_verify_v1'
      or coalesce(new.block_name, '') = 'zalo-chat-referral-precreate-v1';
  end if;
  if tg_op in ('UPDATE', 'DELETE') then
    v_old_reserved := coalesce(old.using_code, '') = 'zalo_chat_referral_verify_v1'
      or coalesce(old.block_name, '') = 'zalo-chat-referral-precreate-v1';
  end if;

  if current_user not in ('postgres', 'service_role') and (v_old_reserved or v_new_reserved) then
    raise exception using errcode = '42501', message = 'zalo_referral_ai_log_backend_only';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

