CREATE OR REPLACE FUNCTION public.aka_agent_call_email_notification_worker(p_mode text DEFAULT 'process'::text, p_reason text DEFAULT 'manual'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'net'
AS $function$
DECLARE
  v_url text := public.aka_agent_get_vault_secret('AKA_AGENT_EMAIL_NOTIFICATION_WORKER_URL');
  v_token text := public.aka_agent_get_vault_secret('INTERNAL_EDGE_FUNCTION_TOKEN');
  v_request_id bigint;
BEGIN
  IF v_url IS NULL OR btrim(v_url) = '' OR v_token IS NULL OR btrim(v_token) = '' THEN
    RAISE NOTICE 'Email notification worker URL/token is not configured in Supabase Vault.';
    RETURN NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    RAISE NOTICE 'pg_net extension is not installed; email notification worker was not invoked.';
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-token', v_token
    ),
    body := jsonb_build_object(
      'mode', COALESCE(NULLIF(p_mode, ''), 'process'),
      'reason', COALESCE(NULLIF(p_reason, ''), 'manual')
    )
  )
  INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  d text;
begin
  if p is null then
    return null;
  end if;
  d := regexp_replace(p, '[^0-9]', '', 'g');
  if d = '' then
    return '';
  end if;
  if d like '0084%' and length(d) >= 13 then
    d := '0' || substr(d, 5);
  elsif d like '84%' and length(d) >= 11 then
    d := '0' || substr(d, 3);
  end if;
  if length(d) = 9 and left(d, 1) in ('3','5','7','8','9') then
    d := '0' || d;
  end if;
  if length(d) = 11 and left(d, 1) = '0' then
    d := case left(d, 4)
      when '0162' then '032' when '0163' then '033' when '0164' then '034' when '0165' then '035'
      when '0166' then '036' when '0167' then '037' when '0168' then '038' when '0169' then '039'
      when '0120' then '070' when '0121' then '079' when '0122' then '077' when '0126' then '076'
      when '0128' then '078' when '0123' then '083' when '0124' then '084' when '0125' then '085'
      when '0127' then '081' when '0129' then '082' when '0186' then '056' when '0188' then '058'
      when '0199' then '059'
      else left(d, 4)
    end || substr(d, 5);
  end if;
  return d;
end;
$function$
